    if (pr && pr.checks && ACTIVE_RUN_STATES.indexOf(pr.checks.verdict) !== -1) {
        return 'pr_validation';
    }
    return 'pr_created';
}

var LANE_ORDER = ['development', 'pr_created', 'pr_validation', 'review',
                  'approved_queue', 'validating', 'merged_recent'];

