        { leg: 'dev', at: '2026-10-03T07:00:00Z', prompt: 1000,
          completion: 500, total: 1500, model: 'mystery-model' }
      ] }
    });
    var row = cardFor(st, 31).tokens[0];
    assert.equal(row.model, 'mystery-model', 'the model still renders');
