    var t = runClock(r);
    return {
        verdict: runVerdictOf(r),
        at: r.created_at,
        url: r.html_url,
        runId: r.id == null ? null : r.id,
        name: r.name || null,
        sha: r.head_sha || null,
        conclusion: runConclusionOf(r),
