    card.queuePos = null;
    card._now = now;
    var lane = laneOf({ labels: card.labels, checks: card.checks });
    mergeLabelTimestamps(card, pix.pr[pr.number], hasPrev);
    card.history = nextHistory(pix.pr[pr.number], pix.prLane[pr.number],
        lane, now, hasPrev);
