function issueEntry(it, ctx) {
    if (it == null || it.number == null) return;
    var inDev = isInDevLeg(it);
    var bucket = backlogBucket(it, ctx.machineAuthor);
    if (isDevDoneVisible(it, bucket)) return;
    var prevCard = ctx.pix.issue[it.number];
    var devStartedAt;
    if (inDev) {
