// that sees the handoff stamps it (tick-cadence exact).
function devStartedAtCarry(prevCard, hasPrev, now) {
    if (prevCard && prevCard.devStartedAt) return prevCard.devStartedAt;
    return hasPrev ? now : undefined;
}

